procedure HardwareRefunds {
  about "Handle refund requests within limits"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Opened return {r.return_no} for {r.customer}. Please review."
    stop "opened return"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Return {r.return_no} is older than 30 days."
    stop "old return"
  }
  if r.amount > $100.00 {
    notify owner "Refund of {r.amount} for {r.return_no} exceeds $100. Please review."
    stop "overlimit refund"
  }
  refund r.amount for r.return_no reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
```

