procedure TattooAftercareFollowUp {
  about "Contact a new client, then follow up once"
  policy TattooPolicy
  sheet Appointments "Appointments" { client: Text, phone: Phone, start: DateTime, artist: Text, deposit: Money, status: Text, design_notes: Text private }
  trigger every day at 14:00

  let all = fetch Appointments
  let first = filter all where status == "done" up to 20
  for each r in first up to 20 {
    let m1 = draft sms to r.phone: "Hi {r.client default 'there'}, thanks for choosing the shop! Reply with any questions."
    let ok1 = request approval of m1 from owner timeout 12 hours else skip
    send ok1
    update r set status = "contacted"
    wait 3 days
    let now_all = fetch Appointments
    let recent = filter now_all where phone == r.phone and status != "done" up to 20
    if is_empty(recent) {
      stop "already handled"
    }
    let m2 = draft sms to r.phone: "Hi {r.client default 'there'}, just checking in. Is there anything we can help with?"
