  about "Aether cannot do this; list the customers for the owner"
  policy MovePolicy
  sheet Moves "Moves" { customer: Text, phone: Phone, move_date: Date, crew: Text, deposit: Money, estimate: Money, status: Text, access_notes: Text private }
  trigger every day at 15:00

  let all = fetch Moves
  let these = filter all where status == "booked" and crew == "" and days_between(move_date, today()) <= 5
  for each r in these up to 15 {
    notify owner "{r.customer} ({r.move_date}): assign the crew yourself."
  }
}

