procedure MoveRefund {
  about "Refund a deposit and update the record"
  policy MovePolicy
  sheet MoveCancellations "MoveCancellations" { job: Text, customer: Text, phone: Phone, deposit: Money, move_date: Date }
  trigger when new row r in MoveCancellations

  if days_between(r.move_date, today()) <= 7 {
    notify owner "Short-notice refund for {r.job} ({r.deposit}). Please handle it."
    stop "short notice goes to owner"
  }
  if r.deposit > $200.00 {
    notify owner "Deposit of {r.deposit} for {r.job} is over $200. Please review."
    stop "over $200 goes to owner"
  }
  refund r.deposit for r.job reason "move cancellation", ask owner first timeout 1 day else stop "refund not approved"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your deposit of {r.deposit} has been refunded."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
```

