procedure MoveDailySummary {
  about "Tell the owner how many customers are booked"
  policy MovePolicy
  sheet Moves "Moves" { customer: Text, phone: Phone, move_date: Date, crew: Text, deposit: Money, estimate: Money, status: Text, access_notes: Text private }
  trigger every monday at 07:00

  let all = fetch Moves
  let these = filter all where status == "booked"
  let n = summarize count of these
  let total = summarize sum estimate of these
  if n == 0 {
    stop "no booked customers"
  }
  let avg = total / n
  if avg > $100.00 {
    notify owner "Booked customers are very expensive ({avg}). Please review."
    stop "expensive booked customers"
  }
  notify owner "Booked customers: {n}, total estimate: {total}, average estimate: {avg}"
}
```

