procedure RoofOrderReplenishment {
  about "Replenish our shingle stock below 20"
  policy RoofPolicy
  sheet Materials "Materials" { material: Text, on_hand: Number, unit_cost: Money }
  trigger every monday at 06:00

  let all = fetch Materials
  let low = filter all where material == "shingles" and on_hand < 20
  let n = summarize count of low
  if n == 0 {
    stop "already above 20"
  }
  notify owner "Shingles below 20: order some more."
  order "50 bundles of shingles" from AcmeSupply cost $750.00, ask owner first timeout 1 day else stop "order not approved"
  log "ordered 50 bundles"
}

